<?php declare(strict_types=1); final class SearchController extends Controller { public function index(): void { $q=trim((string)($_GET['q']??''));$type=$_GET['type']??'all';$db=Database::connection();$jobs=[];$freelancers=[];if($q!==''){if($type==='all'||$type==='jobs'){$s=$db->prepare("SELECT j.*,p.display_name AS employer_name FROM jobs j LEFT JOIN profiles p ON p.user_id=j.employer_id WHERE j.status='open' AND (j.title LIKE :q OR j.description LIKE :q) ORDER BY j.created_at DESC LIMIT 30");$s->execute(['q'=>'%'.$q.'%']);$jobs=$s->fetchAll();}if($type==='all'||$type==='freelancers'){$s=$db->prepare("SELECT p.* FROM profiles p JOIN users u ON u.id=p.user_id WHERE u.role='freelancer' AND u.status='active' AND (p.display_name LIKE :q OR p.headline LIKE :q OR p.bio LIKE :q OR p.username LIKE :q) ORDER BY p.rating DESC LIMIT 30");$s->execute(['q'=>'%'.$q.'%']);$freelancers=$s->fetchAll();}}$this->view('search/results',['title'=>'نتایج جستجو','q'=>$q,'type'=>$type,'jobs'=>$jobs,'freelancers'=>$freelancers]); } }